INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷82·晋少帝本纪·天福八年九月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7bc781abc574bfda6b3d4fe1b21ccaaaf8a0ef7e/content/books/zizhi-tongjian/vol-283/year-0943/part-04/sources/library/jiuwudaishi-082-943-september/source.txt", "note": "《旧五代史》卷82·晋少帝本纪·天福八年九月，段落 jiu-wudaishi-205deb4a7860-p001995；已核上下文及传主，纸本及异文待核。", "id": "e1ae6f03-8062-5d61-9a4d-9f119107b9cd"}, {"title": "旧五代史·卷89·冯玉传", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7bc781abc574bfda6b3d4fe1b21ccaaaf8a0ef7e/content/books/zizhi-tongjian/vol-283/year-0943/part-04/sources/library/jiuwudaishi-089-feng-yu/source.txt", "note": "《旧五代史》卷89·冯玉传，段落 jiu-wudaishi-205deb4a7860-p002144；已核上下文及传主，纸本及异文待核。", "id": "18569c3f-9e32-58d3-a7d2-ead68bc8f1de"}, {"title": "资治通鉴·卷283·天福八年·八月至十一月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7bc781abc574bfda6b3d4fe1b21ccaaaf8a0ef7e/content/books/zizhi-tongjian/vol-283/year-0943/part-04/sources/library/tongjian-283-943-autumn/source.txt", "note": "《资治通鉴》卷283·天福八年·八月至十一月及追述，段落 zizhi-tongjian-a63549944a71-p003368；已核上下文及传主，纸本及异文待核。", "id": "7c14a156-85f0-5f0b-abe1-e2c8cd11fb33"}, {"title": "新五代史·卷17·晋家人传·出帝冯皇后", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7bc781abc574bfda6b3d4fe1b21ccaaaf8a0ef7e/content/books/zizhi-tongjian/vol-283/year-0943/part-04/sources/library/xinwudaishi-017-feng-empress/source.txt", "note": "《新五代史》卷17·晋家人传·出帝冯皇后，段落 xin-wudaishi-b08f244b9241-p000578；已核上下文及传主，纸本及异文待核。", "id": "52374289-3999-52ab-b77f-99d3dcdcbce9"}, {"title": "新五代史·卷17·晋家人传·石重胤", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7bc781abc574bfda6b3d4fe1b21ccaaaf8a0ef7e/content/books/zizhi-tongjian/vol-283/year-0943/part-04/sources/library/xinwudaishi-017-shi-chongyin/source.txt", "note": "《新五代史》卷17·晋家人传·石重胤，段落 xin-wudaishi-b08f244b9241-p000581；已核上下文及传主，纸本及异文待核。", "id": "0a5687e6-90d0-5323-823b-68cd37f49381"}, {"title": "新五代史·卷62·南唐世家·讨张遇贤", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7bc781abc574bfda6b3d4fe1b21ccaaaf8a0ef7e/content/books/zizhi-tongjian/vol-283/year-0943/part-04/sources/library/xinwudaishi-062-zhang-defeat/source.txt", "note": "《新五代史》卷62·南唐世家·讨张遇贤，段落 xin-wudaishi-b08f244b9241-p003138；已核上下文及传主，纸本及异文待核。", "id": "2184fc79-93a7-57d6-84c5-0772242055c7"}, {"title": "资治通鉴·卷283·天福八年·四五月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0492098592de640119d51b379b17908f65b59b0/content/books/zizhi-tongjian/vol-283/year-0943/part-02/sources/library/tongjian-283-943-april-may/source.txt", "note": "《资治通鉴》卷283·天福八年·四五月及追述，段落 zizhi-tongjian-a63549944a71-p003367；已核上下文及传主，纸本及异文待核。", "id": "8e1284b2-bd81-5ec3-9d02-501f6839c4d0"}, {"title": "新五代史·卷65·南汉世家·刘晟继位", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0492098592de640119d51b379b17908f65b59b0/content/books/zizhi-tongjian/vol-283/year-0943/part-02/sources/library/xinwudaishi-065-liu-sheng-accession/source.txt", "note": "《新五代史》卷65·南汉世家·刘晟继位，段落 xin-wudaishi-b08f244b9241-p003281；已核上下文及传主，纸本及异文待核。", "id": "ac3719db-7597-59f3-ad72-ea42a782a2d1"}, {"title": "新五代史·卷9·晋出帝本纪·天福八年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0bf9f2cc5934c50fb020b79750ac51ac7d48f541/content/books/zizhi-tongjian/vol-283/year-0943/part-01/sources/library/xinwudaishi-009-943-return/source.txt", "note": "《新五代史》卷9·晋出帝本纪·天福八年，段落 xin-wudaishi-b08f244b9241-p000334；已核上下文及传主，纸本及异文待核。", "id": "8b6277d6-bc14-525d-a7c0-ae15a89bdca9"}, {"title": "新五代史·卷62·南唐世家·李璟与诸弟", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0bf9f2cc5934c50fb020b79750ac51ac7d48f541/content/books/zizhi-tongjian/vol-283/year-0943/part-01/sources/library/xinwudaishi-062-jing-brothers/source.txt", "note": "《新五代史》卷62·南唐世家·李璟与诸弟，段落 xin-wudaishi-b08f244b9241-p003137；已核上下文及传主，纸本及异文待核。", "id": "4eec6cb7-f426-58dc-9677-661a25ec2fce"}, {"title": "新五代史·卷29·景延广传·晋与契丹交涉", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f7f6cfbef8465951e2f967177b4e0970e9d71ed0/content/books/zizhi-tongjian/vol-283/year-0942/part-05/sources/library/xinwudaishi-029-jing-khitan/source.txt", "note": "《新五代史》卷29·景延广传·晋与契丹交涉，段落 xin-wudaishi-b08f244b9241-p001067；已核上下文及传主，纸本及异文待核。", "id": "82078cac-bb42-5526-b3f6-656e97070284"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "李景逷", "aliases": ["景逷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李昪的幼子，母亲为种氏。种氏曾建议让他继承帝位，李昪拒绝了这一建议。具体年月及生卒年尚未核。", "biography": null, "status": "draft", "id": "ce31a798-a913-59fb-a388-d623c7483ca8"}, {"name": "宋氏（南唐李昪后）", "aliases": ["宋氏（李昪后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李昪的皇后。937年被立为皇后，939年与李昪为李氏父母服丧。个人名字及生卒年本次未核。", "biography": null, "status": "draft", "id": "87d8df9d-227e-5ea6-9284-514b5a1aebcd"}, {"name": "拓跋崇斌", "aliases": ["拓拔崇斌"], "era": "五代十国", "birth_year": null, "death_year": 943, "description": "夏州牙内指挥使，943年谋作乱，李彝敏准备相助。《旧五代史》九月奏报称拓拔崇斌等五人已经被捕斩；拓跋、拓拔字形分别保留，处刑确切日未载。出生年未载。", "biography": null, "status": "draft", "id": "5619f0e5-2b51-5320-ad47-a8fa28029d64"}, {"name": "李彝敏", "aliases": ["李彜敏"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋绥州刺史。943年准备帮助拓跋崇斌作乱，事泄后与弟李彝俊等奔延州。九月，李彝殷奏报其事，朝廷下令送夏州处斩。两书此处主要记诏令，实际执行日尚未核，不据此补精确死亡日。", "biography": null, "status": "draft", "id": "449e568c-f826-5429-a720-96ce53163f00"}, {"name": "李彝俊", "aliases": ["李彜俊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李彝敏的弟弟。943年八月辛未随李彝敏等弃绥州奔延州。生卒年未载。", "biography": null, "status": "draft", "id": "da61a891-98ad-57c9-9a17-c3c343d74521"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "安氏（石重贵母）", "aliases": ["安氏"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安氏（石重贵母），石重贵之母亲。", "biography": null, "status": "draft", "id": "007fcf3c-6da4-54ec-9554-a112cebe061f"}, {"name": "乔荣", "aliases": ["喬榮", "乔莹", "喬瑩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "原河阳牙将，随赵延寿入契丹后任回图使，在后晋经商并在大梁设邸。943年遭囚禁和没收货物，获释后把景延广的外交言辞写下并报给耶律德光。《新五代史》相同场景作喬瑩，据行动、对话和纸上记录对应同人，姓名异文与纸本待核。生卒年未载。", "biography": null, "status": "draft", "id": "2ae2b70e-45d7-5571-9504-de53081be0fd"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "景延广", "aliases": ["景延廣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：景延广，原客将、获任者。", "biography": null, "status": "draft", "id": "de8a964e-a028-50ee-8d54-2cbfda481e98"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "李彝殷", "aliases": ["李彜殷", "李彝兴", "李彝興"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李彝殷，行军司马、权知军州事者。", "biography": null, "status": "draft", "id": "22edc111-ae26-5bce-a26b-3ae072425377"}, {"name": "冯氏（石重贵后）", "aliases": ["吴国夫人冯氏", "馮氏（石重贵后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯濛的女儿、冯玉的妹妹。先嫁石重胤，夫死后守寡；石敬瑭去世后被石重贵纳入宫中，943年十月戊申由吴国夫人立为皇后，随后参与政务。具体个人名字与生卒年未载。", "biography": null, "status": "draft", "id": "a9036cf2-4b6b-5883-a952-511979eb35f7"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "石重胤", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石敬瑭称为少弟的人，又被石敬瑭收养为子。娶冯濛之女，早逝。《新五代史》明确说不知其与石敬瑭的血亲亲疏，故不强建唯一同父兄弟关系；养父关系明确。生卒具体年月尚未核。", "biography": null, "status": "draft", "id": "d1dd86a4-e891-55d3-972a-00409b9b54e8"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "永宁公主（石敬瑭妻）", "aliases": ["永宁公主", "永寧公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：永宁公主（石敬瑭妻），与从荣异母的公主。", "biography": null, "status": "draft", "id": "fddc7a96-9cc5-5313-ac24-2c3189930825"}, {"name": "冯玉", "aliases": ["馮玉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯皇后的兄长，后晋官员。《资治通鉴》记其由礼部郎中、盐铁判官被迅速擢为端明殿学士、户部侍郎；《旧五代史》另记知制诰、中书舍人、颍州团练使等任职。各书路径分别保留，生卒年本批未核。", "biography": null, "status": "draft", "id": "b4626ebf-1219-5b9b-baca-73e491e175f8"}, {"name": "冯濛", "aliases": ["馮濛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安喜人，后晋冯皇后的父亲，曾任邺都副留守。《新五代史》还记他曾是定州进奏吏，居京师，受到安重诲赏识。生卒年未载。", "biography": null, "status": "draft", "id": "3d20e6b7-4094-501c-b590-43f2726ba61c"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "刘弘雅", "aliases": ["劉弘雅", "刘洪雅", "劉洪雅"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘雅，获封王爵之子。", "biography": null, "status": "draft", "id": "b03cbc36-bab1-5094-9267-00775e6297a1"}, {"name": "严恩", "aliases": ["嚴恩", "严思", "嚴思"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐洪州营屯都虞候。943年十月奉李璟命率兵讨张遇贤，与监军边镐共事。《新五代史》同一战役作嚴思，依据军职及边镐、张遇贤对应同人，保留姓名异文待纸本核。生卒年未载。", "biography": null, "status": "draft", "id": "22f2f94d-19c0-589d-b9a4-a52fa5982372"}, {"name": "边镐", "aliases": ["邊鎬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "金陵人，南唐通事舍人。943年十月任讨张遇贤军监军，用白昌裕为谋主，接连获胜；白昌裕建议开道绕到营后袭击，张遇贤随后逃走被捕。生卒年尚未核。", "biography": null, "status": "draft", "id": "8bcc0004-3382-5f6c-af6e-73ccf4cdd725"}, {"name": "白昌裕", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐讨张遇贤军的谋主，由边镐任用，曾建议伐木开道绕到张遇贤营后袭击。《资治通鉴》籍贯写虞州，保留原地名待核，不自行改为虔州。生卒年未载。", "biography": null, "status": "draft", "id": "759d3f84-b61e-588b-89ce-149c96c966ef"}, {"name": "张遇贤", "aliases": ["張遇賢"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "博罗县吏。942年循州起事者拥立他为领袖，他称中天八国王、改元永乐并置官。南汉派刘弘昌、刘弘杲征讨，二人在钱帛馆被围，后由将领救出。生卒年未载。", "biography": null, "status": "draft", "id": "508b1255-a234-507d-a64f-ede078d1c559"}, {"name": "李台", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "张遇贤属下别将。943年十月张遇贤弃众投奔他，他认为神言无验，擒张遇贤投降，张遇贤后来在金陵市被斩。生卒年未载。", "biography": null, "status": "draft", "id": "faecc235-ace8-595d-a5ec-bcd7a94ce8fc"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

